#!/usr/bin/env python3
"""Build the shipment summary described in /app/docs/summary-format.md."""
import csv
import datetime as dt
import gzip
import io
import json
import os
import re
import sys
import xml.etree.ElementTree as ET
from decimal import Decimal, ROUND_HALF_UP
from fractions import Fraction

KG = {"kg": Fraction(1), "g": Fraction(1, 1000), "lb": Fraction("0.45359237"),
      "oz": Fraction("0.028349523125")}
UNIT_ALIAS = {"kgs": "kg", "lbs": "lb", "ozs": "oz", "gram": "g", "grams": "g"}
PRIORITY = ["central", "south", "east", "river", "north", "west", "harbor", "lakeside"]
COLUMNS = {
    "east": {"id", "type", "shipped", "gross", "net", "status", "note"},
    "lakeside": {"id", "kind", "booked", "shipped", "gross_kg", "net_kg", "status"},
    "river": {"t", "ref", "shipped", "weight", "status"},
    "west": {"id", "typ", "shipped", "weight", "status", "note"},
    "harbor": {"rec", "ref", "date", "weight", "state"},
}
DELIM = {"east": ",", "lakeside": ",", "river": "\t", "west": ";", "harbor": "|"}
BASE_DATE = {"east": "ymd", "lakeside": "iso", "river": "mm/dd/yyyy",
             "west": "dd.mm.yyyy", "harbor": "iso"}
HARBOR_STATE = {"DLV": "delivered", "DLL": "delivered_late", "CAN": "cancelled",
                "RET": "returned", "HLD": "held"}
FW_STATUS = {"D": "delivered", "L": "delivered_late", "C": "cancelled",
             "R": "returned", "H": "held"}
MONTHS = {m: i + 1 for i, m in enumerate(
    ["jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct", "nov", "dec"])}


def read_text(path):
    with open(path, "rb") as f:
        b = f.read()
    if b[:2] == b"\x1f\x8b":
        b = gzip.decompress(b)
    if b[:3] == b"\xef\xbb\xbf":
        return b[3:].decode("utf-8", "replace")
    if b[:2] == b"\xff\xfe":
        return b[2:].decode("utf-16-le", "replace")
    if b[:2] == b"\xfe\xff":
        return b[2:].decode("utf-16-be", "replace")
    enc = "utf-8"
    m = re.search(rb"^#\s*charset\s*:\s*([\w.-]+)", b[:2000], re.M | re.I)
    if m:
        enc = m.group(1).decode("ascii")
    try:
        return b.decode(enc, "replace")
    except LookupError:
        return b.decode("utf-8", "replace")


def id_number(s):
    m = re.match(r"^\s*SH\W*0*(\d+)", str(s or ""), re.I)
    return int(m.group(1)) if m else None


def rtype(v):
    v = str(v or "").strip().lower()
    if v.startswith("v"):
        return "void"
    if v.startswith(("c", "a")):
        return "correction"
    return "new"


def norm_status(s):
    return re.sub(r"[\s\-]+", "_", str(s or "").strip().lower())


def norm_unit(u):
    u = str(u or "").strip().lower()
    u = UNIT_ALIAS.get(u, u)
    return u if u in KG else None


def parse_number(s, decimal_comma):
    s = s.strip().replace(" ", "")
    if decimal_comma:
        s = s.replace(".", "").replace(",", ".")
    else:
        s = s.replace(",", "")
    return Fraction(s)


def parse_weight(s, decimal_comma, *units):
    """Return weight in kg. units: candidates in order of decreasing priority."""
    m = re.match(r"^\s*([-+]?[\d.,\s]*\d)\s*([A-Za-z]+)?\s*$", str(s))
    if not m:
        return None
    try:
        num = parse_number(m.group(1), decimal_comma)
    except (ValueError, ZeroDivisionError):
        return None
    unit = norm_unit(m.group(2)) if m.group(2) else None
    for u in (unit,) + units:
        if u:
            return num * KG[u]
    return num


def date_from_ordinal(y, d):
    return dt.date(y, 1, 1) + dt.timedelta(days=d - 1)


def parse_time(s, form):
    """Return a UTC date for a ship date or ship time."""
    s = str(s).strip()
    if re.match(r"^\d{4}-\d\d-\d\d[T ]", s):
        t = s.replace(" ", "T", 1)
        d = dt.datetime.fromisoformat(t.replace("Z", "+00:00"))
        if d.tzinfo is not None:
            d = d.astimezone(dt.timezone.utc)
        return d.date()
    m = re.match(r"^(\d{1,2})\s+([A-Za-z]{3})[a-z]*\.?,?\s+(\d{4})$", s)
    if m:
        return dt.date(int(m.group(3)), MONTHS[m.group(2).lower()], int(m.group(1)))
    form = (form or "iso").strip().lower()
    if form == "serial" or re.match(r"^\d+(\.\d+)?$", s) and form == "serial":
        return dt.date(1899, 12, 31) + dt.timedelta(days=int(float(s)))
    if re.match(r"^\d{8}$", s):
        return dt.date(int(s[:4]), int(s[4:6]), int(s[6:]))
    if re.match(r"^\d{7}$", s):
        return date_from_ordinal(int(s[:4]), int(s[4:]))
    p = [int(x) for x in re.split(r"\D+", s) if x]
    if len(p) != 3:
        raise ValueError(s)
    if form in ("iso", "ymd", "yyyy-mm-dd", "yyyy/mm/dd"):
        return dt.date(p[0], p[1], p[2])
    if form in ("dmy", "dd/mm/yyyy", "dd.mm.yyyy", "dd-mm-yyyy"):
        return dt.date(p[2], p[1], p[0])
    if form in ("mdy", "mm/dd/yyyy", "mm-dd-yyyy"):
        return dt.date(p[2], p[0], p[1])
    if p[0] > 31:
        return dt.date(p[0], p[1], p[2])
    return dt.date(p[2], p[1], p[0])


def make(num, typ, date_s, form, weight, status):
    """Build a record; weight is kg Fraction, date is a UTC date or None."""
    rec = {"num": num, "type": typ, "kg": weight, "month": None, "status": norm_status(status)}
    if typ != "void" and date_s not in (None, ""):
        try:
            d = parse_time(date_s, form)
            rec["month"] = "%04d-%02d" % (d.year, d.month)
        except (ValueError, KeyError):
            pass
    return rec


# ---------------------------------------------------------------- delimited
def split_records(text, quoted):
    """Yield ('comment', line) or ('row', raw_text) honouring quoted fields."""
    buf = None
    for line in text.split("\n"):
        if line.endswith("\r"):
            line = line[:-1]
        if buf is None:
            if line.startswith("#"):
                yield "comment", line
                continue
            if not line.strip():
                continue
            buf = line
        else:
            buf += "\n" + line
        if not quoted or buf.count('"') % 2 == 0:
            yield "row", buf
            buf = None
    if buf is not None:
        yield "row", buf


def parse_delimited(depot, text):
    seq = None
    delim = DELIM[depot]
    cols = COLUMNS[depot]
    header = None
    unit = None
    date_form = BASE_DATE[depot]
    dcomma = depot == "west"
    out = []
    for kind, raw in split_records(text, delim == ","):
        if kind == "comment":
            m = re.match(r"^#\s*([^:=]+?)\s*:\s*(.*?)\s*$", raw)
            if m:
                name, val = m.group(1).lower(), m.group(2)
                if name == "seq":
                    if seq is None:
                        seq = int(val)
                elif name in ("unit", "weight unit"):
                    u = norm_unit(val.split()[0]) if val.split() else None
                    if u:
                        unit = u
                    if "decimal comma" in val.lower():
                        dcomma = True
                elif name in ("dates", "date format"):
                    date_form = val
            else:
                m = re.search(r"\bseq\s*=\s*(\d+)", raw)
                if m and seq is None:
                    seq = int(m.group(1))
            continue
        row = next(csv.reader([raw], delimiter=delim)) if delim == "," else raw.split(delim)
        if all(f.strip().lower() in cols for f in row):
            header = [f.strip().lower() for f in row]
            continue
        if header is None:
            continue
        wi = next((i for i, h in enumerate(header)
                   if h in ("weight", "gross") or h.startswith(("weight_", "gross_"))), None)
        row_unit = None
        if len(row) == len(header) + 1 and wi is not None:
            idx = wi + 1 if norm_unit(row[wi + 1]) else next(
                (i for i, f in enumerate(row) if norm_unit(f)), None)
            if idx is not None:
                row_unit = norm_unit(row[idx])
                row = row[:idx] + row[idx + 1:]
        if len(row) < len(header):
            row = row + [""] * (len(header) - len(row))
        d = dict(zip(header, row))
        num = id_number(d.get("id") or d.get("ref"))
        if num is None:
            continue
        typ = rtype(d.get("type") or d.get("kind") or d.get("typ") or d.get("t") or d.get("rec"))
        status = d.get("status") if "status" in d else d.get("state", "")
        if depot == "harbor":
            status = HARBOR_STATE.get(str(status).strip().upper(), status)
        kg = None
        if typ != "void" and wi is not None:
            name_unit = None
            m = re.search(r"_(kg|g|lb|oz)$", header[wi])
            if m:
                name_unit = m.group(1)
            kg = parse_weight(row[wi], dcomma, name_unit, row_unit, unit, "kg")
        out.append(make(num, typ, d.get("shipped") or d.get("date"), date_form, kg, status))
    return seq, out


# --------------------------------------------------------------------- json
def parse_json(text):
    seq = None
    out = []
    for line in text.split("\n"):
        line = line.strip()
        if not line:
            continue
        try:
            v = json.loads(line)
        except ValueError:
            continue
        for o in (v if isinstance(v, list) else [v]):
            if not isinstance(o, dict):
                continue
            if "meta" in o and isinstance(o["meta"], dict):
                if seq is None and "seq" in o["meta"]:
                    seq = int(o["meta"]["seq"])
                continue
            num = id_number(o.get("id"))
            if num is None:
                continue
            typ = rtype(o.get("kind"))
            kg = None
            if typ != "void":
                for k, val in o.items():
                    m = re.match(r"^weight(?:_(kg|g|lb|oz))?$", k)
                    if m and val is not None:
                        kg = parse_weight(str(val), False, m.group(1), norm_unit(o.get("unit")), "kg")
                        break
            out.append(make(num, typ, o.get("shipped_at"), "iso", kg, o.get("status")))
    return seq, out


# ---------------------------------------------------------------------- xml
def parse_xml(text):
    text = re.sub(r"^\s*<\?xml[^>]*\?>", "", text)
    root = ET.fromstring(text)
    seq = int(root.get("seq")) if root.get("seq") else None
    runit = norm_unit(root.get("weight-unit"))
    out = []
    for el in root.iter("shipment"):
        def get(name):
            c = el.find(name)
            if c is not None:
                return (c.text or "").strip(), c
            return el.get(name), None
        num = id_number(el.get("id"))
        if num is None:
            continue
        typ = rtype(el.get("type"))
        kg = None
        if typ != "void":
            w, wel = get("weight")
            if w not in (None, ""):
                u = norm_unit(wel.get("unit")) if wel is not None else None
                u = u or norm_unit(el.get("unit"))
                kg = parse_weight(w, False, u, runit, "kg")
        shipped, _ = get("shipped")
        status, _ = get("status")
        out.append(make(num, typ, shipped, "iso", kg, status))
    return seq, out


# -------------------------------------------------------------- fixed width
FW = {
    "FW1": dict(len=42, type=(9, 10), id=(0, 9), shipped=(10, 17), weight=(17, 25), status=(25, 26),
                wfmt=lambda n: Fraction(n) * KG["g"], dfmt="ord"),
    "FW2": dict(len=43, type=(0, 1), id=(1, 10), shipped=(10, 18), weight=(18, 26), status=(26, 27),
                wfmt=lambda n: Fraction(n, 100), dfmt="ymd"),
    "FW3": dict(len=41, type=(16, 17), id=(0, 9), shipped=(9, 16), weight=(17, 24), status=(24, 25),
                wfmt=lambda n: Fraction(n, 10) * KG["lb"], dfmt="ord"),
}


def parse_fixed(text):
    seq = None
    layout = None
    out = []
    by_len = {v["len"]: k for k, v in FW.items()}
    for line in text.split("\n"):
        line = line.rstrip("\r")
        if line.startswith("#"):
            m = re.match(r"^#LAYOUT\s+(\S+)", line)
            if m:
                layout = m.group(1).upper()
            m = re.match(r"^#SEQ\s+(\d+)", line)
            if m and seq is None:
                seq = int(m.group(1))
            continue
        if not line.strip() or line.startswith("\x0c"):
            continue
        name = by_len.get(len(line), layout)
        if name not in FW or (name != layout and len(line) not in by_len):
            continue
        L = FW[name]
        if len(line) != L["len"]:
            continue
        f = lambda k: line[L[k][0]:L[k][1]]
        num = id_number(f("id"))
        if num is None:
            continue
        typ = rtype(f("type"))
        kg = date = None
        if typ != "void":
            try:
                kg = L["wfmt"](int(f("weight")))
            except ValueError:
                pass
            date = f("shipped").strip()
        status = FW_STATUS.get(f("status").strip().upper(), "")
        out.append(make(num, typ, date, "iso", kg, status))
    return seq, out


# --------------------------------------------------------------------- main
def parse_file(depot, path):
    text = read_text(path)
    head = text.lstrip()[:1]
    if depot in COLUMNS:
        return parse_delimited(depot, text)
    if depot == "north" or head in "{[":
        return parse_json(text)
    if head == "<":
        return parse_xml(text)
    return parse_fixed(text)


def main(data_dir, out_file):
    files = {}
    for name in sorted(os.listdir(data_dir)):
        p = os.path.join(data_dir, name)
        if os.path.isfile(p):
            files.setdefault(name.split("-")[0], []).append(p)
    corrections = resends = 0
    current = {}
    for depot, paths in files.items():
        exports = []
        for i, p in enumerate(paths):
            seq, recs = parse_file(depot, p)
            exports.append((seq if seq is not None else -1, i, recs))
        exports.sort(key=lambda e: (e[0], e[1]))
        cur = {}
        for _, _, recs in exports:
            for r in recs:
                n = r["num"]
                if r["type"] == "new":
                    if n in cur:
                        resends += 1
                    else:
                        cur[n] = r
                elif r["type"] == "correction":
                    cur[n] = r
                    corrections += 1
                else:
